import * as React from 'react';
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import Container from '@mui/material/Container';
import Grid from '@mui/material/Grid';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesome';
import DesignServicesIcon from '@mui/icons-material/DesignServices';
import RocketLaunchIcon from '@mui/icons-material/RocketLaunch';
import InsightsIcon from '@mui/icons-material/Insights';

/**
 * Service highlights data
 * Each entry represents a core service offering
 */
const highlights = [
  {
    icon: <DesignServicesIcon />,
    title: 'Strategic Design',
    description: 'We blend aesthetics with functionality to create user-centric designs that drive engagement and conversion.',
  },
  {
    icon: <InsightsIcon />,
    title: 'Digital Innovation',
    description: 'Leveraging cutting-edge technologies to build scalable solutions that keep you ahead of the competition.',
  },
  {
    icon: <RocketLaunchIcon />,
    title: 'Growth Solutions',
    description: 'Data-driven strategies that accelerate your business growth and maximize market opportunities.',
  },
  {
    icon: <AutoAwesomeIcon />,
    title: 'Brand Evolution',
    description: 'Transform your brand identity with compelling digital experiences that resonate with your audience.',
  },
];

/**
 * HighlightCard Component
 * Displays individual service offering with icon and description
 */
function HighlightCard({ icon, title, description }) {
  return (
    <Card
      component="article"
      elevation={0}
      sx={{
        height: '100%',
        background: 'rgba(30, 30, 30, 0.4)',
        backdropFilter: 'blur(8px)',
        border: '1px solid',
        borderColor: 'divider',
        transition: 'all 0.3s ease-in-out',
        position: 'relative',
        overflow: 'hidden',
        '&:hover': {
          transform: 'translateY(-4px)',
          '& .title': {
            background: 'linear-gradient(90deg, #90CAF9, #64B5F6)',
            backgroundClip: 'text',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          },
          '& .icon': {
            color: '#90CAF9',
            transform: 'scale(1.1)',
          },
        },
      }}
    >
      <Stack
        spacing={3}
        sx={{
          p: 3.5,
          height: '100%',
        }}
      >
        <Box
          className="icon"
          sx={{
            color: 'text.secondary',
            transition: 'all 0.3s ease-in-out',
            '& > svg': {
              fontSize: 44,
            },
          }}
        >
          {icon}
        </Box>
        <Box>
          <Typography
            variant="h6"
            component="h3"
            className="title"
            gutterBottom
            sx={{
              fontWeight: 600,
              fontSize: { xs: '1.25rem', sm: '1.5rem' },
              mb: 1.5,
              transition: 'all 0.3s ease-in-out',
            }}
          >
            {title}
          </Typography>
          <Typography
            variant="body1"
            color="text.secondary"
            sx={{
              lineHeight: 1.7,
              fontSize: { xs: '0.875rem', sm: '1rem' },
            }}
          >
            {description}
          </Typography>
        </Box>
      </Stack>
    </Card>
  );
}

/**
 * Highlights Component
 * Showcases core service offerings in a grid layout
 */
export default function Highlights() {
  return (
    <section id="highlights" aria-label="Our Services">
      <Box
        sx={{
          position: 'relative',
          py: { xs: 8, sm: 12, md: 16 },
          background: 'linear-gradient(180deg, transparent, rgba(0, 0, 0, 0.3))',
        }}
      >
        <Container maxWidth="lg">
          <Stack spacing={6}>
            <Box sx={{ textAlign: 'center' }}>
              <Typography
                component="h2"
                variant="h2"
                align="center"
                sx={{
                  fontSize: { xs: '2rem', sm: '2.5rem', md: '3rem' },
                  fontWeight: 700,
                  letterSpacing: '-0.01em',
                  background: 'linear-gradient(90deg, #fff, rgba(255, 255, 255, 0.8))',
                  backgroundClip: 'text',
                  WebkitBackgroundClip: 'text',
                  WebkitTextFillColor: 'transparent',
                  mb: 2,
                }}
              >
                Our Expertise
              </Typography>
              <Typography
                variant="h5"
                component="p"
                sx={{
                  color: 'text.secondary',
                  fontSize: { xs: '1rem', sm: '1.25rem' },
                  maxWidth: '600px',
                  mx: 'auto',
                  mb: { xs: 6, sm: 8 },
                }}
              >
                From Spark to Spotlight: we take you every step of the way to success.
              </Typography>
            </Box>
            <Grid
              container
              spacing={{ xs: 3, md: 4 }}
              sx={{ maxWidth: 1200, mx: 'auto' }}
            >
              {highlights.map((highlight, index) => (
                <Grid item xs={12} sm={6} md={3} key={index}>
                  <HighlightCard {...highlight} />
                </Grid>
              ))}
            </Grid>
          </Stack>
        </Container>
      </Box>
    </section>
  );
}
